// g_local.h's DEFAULT_BULLET_HSPREAD/VSPREAD -- not centralized anywhere in
// the header modules (p_weapon.ts/m_tank.ts/legacy m_soldier.ts each keep
// their own module-local copy too, per that established precedent).
const DEFAULT_BULLET_HSPREAD = 300;
const DEFAULT_BULLET_VSPREAD = 500;

// range at which we'll try to initiate a run-attack to close distance
// (m_infantry.cpp:31)
const RANGE_RUN_ATTACK = 440 * 0.75; // RANGE_NEAR * 0.75f (g_local.ts's RANGE_NEAR)

/** g_local.h:468-469's `FRAME_TIME_S`, worked around per g_phys.ts's/
 *  g_ai.ts's identical `frameTimeAsGtime()` precedent (no InitGame-set
 *  global exists yet in this port line). */
function frameTimeAsGtime(): GTime {
  return Gtime_from_ms(gi.frame_time_ms);
}

/** g_local.h:136-139 `game_import_t::traceline` -- duplicated per-file,
 *  matching g_monster.ts's own (unexported) `giTraceline` precedent (see
 *  its file header's "PLACEMENT-MISMATCH FUNCTIONS PORTED LOCALLY"). */
function giTraceline(start: Vec3, end: Vec3, passent: EdictT | null, mask: ContentsT): KexTraceT {
  return gi.trace(start, null, null, end, passent, mask);
}

/** EDICT_NUM idiom -- duplicated per-file, matching g_monster.ts's/
 *  g_phys.ts's own `traceEdict` precedent (a trace's `.ent` comes back
 *  typed as the narrower `KexEdictT`; this recovers the real `EdictT` via
 *  `g_edicts[]`). */
function traceEdict(ent: KexEdictT | null): EdictT {
  if (ent === null) return g_edicts[0];
  return g_edicts[ent.s.number];
}

// ============================================================================
// Locally-ported small cross-file dependencies (see file header)
// ============================================================================

/** g_local.h:3282 (inline). [Paril-KEX] */
function monster_footstep(self: EdictT): void {
  if (self.groundentity) self.s.event = KexEntityEventT.EV_OTHER_FOOTSTEP;
}

/** g_local.h:3521 (inline). */
function M_CheckGib(self: EdictT, mod: ModT): boolean {
  if (self.deadflag) {
    if (mod.id === ModIdT.MOD_CRUSH) return true;
  }
  return self.health <= self.gib_health;
}

/** rogue/g_rogue_monster.cpp:98. See file header -- ported for real (tiny,
 *  no rogue-specific dependencies), duplicating g_ai.ts's own (unexported,
 *  throwing) stub of the same symbol. */
function monster_done_dodge(self: EdictT): void {
  self.monsterinfo.aiflags &= ~MonsterAiFlagsT.AI_DODGING;
  if (self.monsterinfo.attack_state === MonsterAttackStateT.AS_SLIDING) {
    self.monsterinfo.attack_state = MonsterAttackStateT.AS_STRAIGHT;
  }
}

/** rogue/g_rogue_newai.cpp:1424. */
function monster_duck_down(self: EdictT): void {
  self.monsterinfo.aiflags |= MonsterAiFlagsT.AI_DUCKED;
  self.maxs[2] = self.monsterinfo.base_height - 32;
  self.takedamage = true;
  self.monsterinfo.next_duck_time = Gtime_add(level.time, DUCK_INTERVAL);
  gi.linkentity(self);
}

/** rogue/g_rogue_newai.cpp:1434. */
function monster_duck_hold(self: EdictT): void {
  if (level.time >= self.monsterinfo.duck_wait_time) {
    self.monsterinfo.aiflags &= ~MonsterAiFlagsT.AI_HOLD_FRAME;
  } else {
    self.monsterinfo.aiflags |= MonsterAiFlagsT.AI_HOLD_FRAME;
  }
}

// rogue/g_rogue_newai.cpp:~1440 (MONSTERINFO_UNDUCK) -- `monster_duck_up` is
// monster-agnostic rogue-newai infrastructure, imported from m_soldier.ts
// (its canonical, exported home in this porting batch) rather than
// re-registered here under the same name: g_save_registry.ts's
// monsterinfo_unduck registry is global and name-keyed, so a second local
// copy registered as "monster_duck_up" would throw a duplicate-registration
// error the instant both files load in the same process (as g_spawn.ts's
// real monster table does). See m_soldier.ts's own comment on this export.

/** rogue/g_rogue_newai.cpp:1083-1135. Ported for real -- see file header
 *  ("load-bearing for InfantryMachineGun"). `aimdir`/`aimpoint` mutate the
 *  passed Vec3 in place (matching AngleVectors's established
 *  reference-out-param idiom), rather than the C++ pointer-write, since a
 *  bare TS reassignment of a Vec3 parameter would not be visible to the
 *  caller. The C++ unconditionally dereferences `aimdir` when the target is
 *  missing (`*aimdir = {}`); every real call site always passes a non-null
 *  aimdir, so this port keeps that same assumption without adding a
 *  defensive null branch that isn't in the source. */
function PredictAim(
  self: EdictT,
  target: EdictT | null,
  start: Vec3,
  bolt_speed: number,
  eyeHeightIn: boolean,
  offset: number,
  aimdir: Vec3 | null,
  aimpoint: Vec3 | null,
): void {
  if (!target || !target.inuse) {
    if (aimdir) {
      aimdir[0] = 0;
      aimdir[1] = 0;
      aimdir[2] = 0;
    }
    return;
  }

  let eye_height = eyeHeightIn;
  let dir = vec3_sub(target.s.origin, start);
  if (eye_height) dir[2] += target.viewheight;
  let dist = vec3_length(dir);

  // [Paril-KEX] if our current attempt is blocked, try the opposite one
  const tr = giTraceline(start, vec3_add(start, dir), self, MASK_PROJECTILE);

  if (traceEdict(tr.ent) !== target) {
    eye_height = !eye_height;
    dir = vec3_sub(target.s.origin, start);
    if (eye_height) dir[2] += target.viewheight;
    dist = vec3_length(dir);
  }

  const time = bolt_speed !== 0 ? dist / bolt_speed : 0;

  let vec = vec3_add(target.s.origin, vec3_muls(target.velocity, time - offset));

  // went backwards...
  if (vec3_dot(vec3_normalized(dir), vec3_normalized(vec3_sub(vec, start))) < 0) {
    vec = vec3(target.s.origin[0], target.s.origin[1], target.s.origin[2]);
  } else {
    // if the shot is going to impact a nearby wall from our prediction, just fire it straight.
    if (giTraceline(start, vec, null, MASK_SOLID).fraction < 0.9) {
      vec = vec3(target.s.origin[0], target.s.origin[1], target.s.origin[2]);
    }
  }

  if (eye_height) vec[2] += target.viewheight;

  if (aimdir) {
    const ad = vec3_normalized(vec3_sub(vec, start));
    aimdir[0] = ad[0];
    aimdir[1] = ad[1];
    aimdir[2] = ad[2];
  }
  if (aimpoint) {
    aimpoint[0] = vec[0];
    aimpoint[1] = vec[1];
    aimpoint[2] = vec[2];
  }
}

/** rogue/g_rogue_newai.cpp:14-88. Ported for real -- self-contained, no
 *  nav_path dependency (unlike its sibling `blocked_checkjump`, stubbed
 *  below). `world` is `g_edicts[0]`, matching g_phys.ts's own established
 *  idiom for the same C++ global. `strncmp(classname, "func_plat", 8)`
 *  becomes `.startsWith("func_plat")` -- equivalent for every classname
 *  this codebase actually spawns ("func_plat"/"func_plat2"). */
function blocked_checkplat(self: EdictT, dist: number): boolean {
  if (!self.enemy) return false;

  let playerPosition: number;
  if (self.enemy.absmin[2] >= self.absmax[2]) playerPosition = 1;
  else if (self.enemy.absmax[2] <= self.absmin[2]) playerPosition = -1;
  else playerPosition = 0;

  if (playerPosition === 0) return false;

  let plat: EdictT | null = null;

  if (self.groundentity !== null && self.groundentity !== g_edicts[0] && (self.groundentity.classname ?? "").startsWith("func_plat")) {
    plat = self.groundentity;
  }

  if (!plat) {
    const forward = vec3(0, 0, 0);
    AngleVectors(self.s.angles, forward, null, null);
    const pt1 = vec3_add(self.s.origin, vec3_muls(forward, dist));
    const pt2 = vec3(pt1[0], pt1[1], pt1[2] - 384);

    const trace = giTraceline(pt1, pt2, self, MASK_MONSTERSOLID);
    if (trace.fraction < 1 && !trace.allsolid && !trace.startsolid && trace.ent !== null) {
      const traceEnt = traceEdict(trace.ent);
      if ((traceEnt.classname ?? "").startsWith("func_plat")) plat = traceEnt;
    }
  }

  if (plat && plat.use) {
    if (playerPosition === 1) {
      if (
        (self.groundentity === plat && plat.moveinfo.state === 1 /* STATE_BOTTOM */) ||
        (self.groundentity !== plat && plat.moveinfo.state === 0 /* STATE_TOP */)
      ) {
        plat.use(plat, self, self);
        return true;
      }
    } else if (playerPosition === -1) {
      if (
        (self.groundentity === plat && plat.moveinfo.state === 0 /* STATE_TOP */) ||
        (self.groundentity !== plat && plat.moveinfo.state === 1 /* STATE_BOTTOM */)
      ) {
        plat.use(plat, self, self);
        return true;
      }
    }
  }

  return false;
}

