export const infantry_pain: PainFn = RegisterPain("infantry_pain", (self: EdictT, other: EdictT, _kick: number, _damage: number, mod: ModT): void => {
  // allow turret to pain
  if ((self.monsterinfo.active_move === infantry_move_jump || self.monsterinfo.active_move === infantry_move_jump2) && self.think === monster_think) {
    return;
  }

  monster_done_dodge(self);

  if (level.time < self.pain_debounce_time) {
    if (self.think === monster_think && frandom() < 0.33) {
      self.monsterinfo.dodge?.(self, other, frameTimeAsGtime(), null, false);
    }
    return;
  }

  self.pain_debounce_time = Gtime_add(level.time, Gtime_from_sec(3));

  const n = brandom() ? 1 : 0;

  if (n === 0) gi.sound(self, SoundchanT.CHAN_VOICE, sound_pain1, 1, ATTN_NORM, 0);
  else gi.sound(self, SoundchanT.CHAN_VOICE, sound_pain2, 1, ATTN_NORM, 0);

  if (self.think !== monster_think) return;

  if (!M_ShouldReactToPain(self, mod)) {
    if (self.think === monster_think && frandom() < 0.33) {
      self.monsterinfo.dodge?.(self, other, frameTimeAsGtime(), null, false);
    }
    return; // no pain anims in nightmare
  }

  if (n === 0) M_SetAnimation(self, infantry_move_pain1, false);
  else M_SetAnimation(self, infantry_move_pain2, false);

  // PMM - clear duck flag
  if ((self.monsterinfo.aiflags & MonsterAiFlagsT.AI_DUCKED) !== 0n) {
    monster_duck_up(self);
  }
});

