/** m_infantry.cpp:272-314. See file header's "KNOWN C++ SOURCE QUIRK" note
 *  for the run-attack flash_number expression. */
function InfantryMachineGun(self: EdictT): void {
  if (!self.enemy || !self.enemy.inuse) return; // PGM

  const is_run_attack = self.s.frame >= FRAME_run201 && self.s.frame <= FRAME_run208;

  let flash_number: number;
  let start: Vec3;
  let forward = vec3(0, 0, 0);
  let right = vec3(0, 0, 0);

  if (self.s.frame === FRAME_attak103 || self.s.frame === FRAME_attak311 || is_run_attack || self.s.frame === FRAME_attak416) {
    if (is_run_attack) {
      // See file header "KNOWN C++ SOURCE QUIRK" -- preserved bug-for-bug.
      flash_number = MonsterMuzzleflashIdT.MZ2_INFANTRY_MACHINEGUN_14 + (self.s.frame - MonsterMuzzleflashIdT.MZ2_INFANTRY_MACHINEGUN_14);
    } else if (self.s.frame === FRAME_attak416) {
      flash_number = MonsterMuzzleflashIdT.MZ2_INFANTRY_MACHINEGUN_22;
    } else {
      flash_number = MonsterMuzzleflashIdT.MZ2_INFANTRY_MACHINEGUN_1;
    }
    AngleVectors(self.s.angles, forward, right, null);
    start = M_ProjectFlashSource(self, monsterFlashOffset()[flash_number], forward, right);

    if (self.enemy) {
      PredictAim(self, self.enemy, start, 0, true, -0.2, forward, null);
    } else {
      AngleVectors(self.s.angles, forward, right, null);
    }
  } else {
    flash_number = MonsterMuzzleflashIdT.MZ2_INFANTRY_MACHINEGUN_2 + (self.s.frame - FRAME_death211);

    AngleVectors(self.s.angles, forward, right, null);
    start = M_ProjectFlashSource(self, monsterFlashOffset()[flash_number], forward, right);

    const vec = vec3_sub(self.s.angles, aimangles[flash_number - MonsterMuzzleflashIdT.MZ2_INFANTRY_MACHINEGUN_2]);
    forward = vec3(0, 0, 0);
    AngleVectors(vec, forward, null, null);
  }

  monster_fire_bullet(self, start, forward, 3, 4, DEFAULT_BULLET_HSPREAD, DEFAULT_BULLET_VSPREAD, flash_number);
}

