export const infantry_die: DieFn = RegisterDie("infantry_die", (self: EdictT, inflictor: EdictT, _attacker: EdictT, damage: number, _point: Vec3, mod: ModT): void => {
  // check for gib
  if (M_CheckGib(self, mod)) {
    gi.sound(self, SoundchanT.CHAN_VOICE, gi.soundindex("misc/udeath.wav"), 1, ATTN_NORM, 0);

    const head_gib = self.monsterinfo.active_move !== infantry_move_death3 ? "models/objects/gibs/sm_meat/tris.md2" : "models/monsters/infantry/gibs/head.md2";

    self.s.skinnum = Math.trunc(self.s.skinnum / 2);

    const gibs: GibDefT[] = [
      { gibname: "models/objects/gibs/bone/tris.md2" },
      { count: 3, gibname: "models/objects/gibs/sm_meat/tris.md2" },
      { gibname: "models/monsters/infantry/gibs/chest.md2", type: 16 /* GIB_SKINNED */ },
      { gibname: "models/monsters/infantry/gibs/gun.md2", type: 16 | 32 /* GIB_SKINNED | GIB_UPRIGHT */ },
      { count: 2, gibname: "models/monsters/infantry/gibs/foot.md2", type: 16 /* GIB_SKINNED */ },
      { count: 2, gibname: "models/monsters/infantry/gibs/arm.md2", type: 16 /* GIB_SKINNED */ },
      { gibname: head_gib, type: 4 | 16 /* GIB_HEAD | GIB_SKINNED */ },
    ];
    ThrowGibs(self, damage, gibs);
    self.deadflag = true;
    return;
  }

  if (self.deadflag) return;

  // regular death
  self.deadflag = true;
  self.takedamage = true;

  const n = irandom(3);

  if (n === 0) {
    M_SetAnimation(self, infantry_move_death1, false);
    gi.sound(self, SoundchanT.CHAN_VOICE, sound_die2, 1, ATTN_NORM, 0);
  } else if (n === 1) {
    M_SetAnimation(self, infantry_move_death2, false);
    gi.sound(self, SoundchanT.CHAN_VOICE, sound_die1, 1, ATTN_NORM, 0);
  } else {
    M_SetAnimation(self, infantry_move_death3, false);
    gi.sound(self, SoundchanT.CHAN_VOICE, sound_die2, 1, ATTN_NORM, 0);
  }

  // don't always pop a head gib, it gets old
  if (n !== 2 && frandom() <= 0.25) {
    const head = ThrowGib(self, "models/monsters/infantry/gibs/head.md2", damage, 0 /* GIB_NONE */, self.s.scale);

    if (head) {
      head.s.angles = vec3(self.s.angles[0], self.s.angles[1], self.s.angles[2]);
      head.s.origin = vec3_add(self.s.origin, vec3(0, 0, 32));
      const headDir = vec3_sub(self.s.origin, inflictor.s.origin);
      const len = vec3_length(headDir);
      head.velocity = len !== 0 ? vec3_muls(headDir, 100.0 / len) : vec3(0, 0, 0);
      head.velocity[2] = 200.0;
      head.avelocity = vec3_muls(head.avelocity, 0.15);
      head.s.skinnum = 0;
      gi.linkentity(head);
    }
  }
});

