function infantry_set_firetime(self: EdictT): void {
  self.monsterinfo.fire_wait = Gtime_add(level.time, random_time(Gtime_from_ms(700), Gtime_from_ms(2000)));

  if (
    (self.monsterinfo.aiflags & MonsterAiFlagsT.AI_STAND_GROUND) === 0n &&
    self.enemy &&
    range_to(self, self.enemy) >= RANGE_RUN_ATTACK &&
    ai_check_move(self, 8.0)
  ) {
    M_SetAnimation(self, infantry_move_attack4, false);
  }
}

function infantry_cock_gun(self: EdictT): void {
  gi.sound(self, SoundchanT.CHAN_WEAPON, sound_weapon_cock, 1, ATTN_NORM, 0);
  // gun cocked
  self.count = 1;
}

function infantry_fire(self: EdictT): void {
  InfantryMachineGun(self);

  // we fired, so we must cock again before firing
  self.count = 0;

  // check if we ran out of firing time
  if (self.monsterinfo.active_move === infantry_move_attack4) {
    if (level.time >= self.monsterinfo.fire_wait) {
      monster_done_dodge(self);
      M_SetAnimation(self, infantry_move_attack1, false);
      self.monsterinfo.nextframe = FRAME_attak114;
    } else if (!ai_check_move(self, 8.0)) {
      // got close to an edge
      M_SetAnimation(self, infantry_move_attack1, false);
      self.monsterinfo.nextframe = FRAME_attak103;
      monster_done_dodge(self);
      self.monsterinfo.attack_state = MonsterAttackStateT.AS_STRAIGHT;
    }
  } else if (
    (self.s.frame >= FRAME_attak101 && self.s.frame <= FRAME_attak115) ||
    (self.s.frame >= FRAME_attak301 && self.s.frame <= FRAME_attak315) ||
    (self.s.frame >= FRAME_attak401 && self.s.frame <= FRAME_attak424)
  ) {
    if (level.time >= self.monsterinfo.fire_wait) {
      self.monsterinfo.aiflags &= ~MonsterAiFlagsT.AI_HOLD_FRAME;

      if (self.s.frame === FRAME_attak416) self.monsterinfo.nextframe = FRAME_attak420;
    } else {
      self.monsterinfo.aiflags |= MonsterAiFlagsT.AI_HOLD_FRAME;
    }
  }
}

