const infantry_attack: MonsterinfoAttackFn = RegisterMonsterinfoAttack("infantry_attack", (self: EdictT): void => {
  monster_done_dodge(self);

  if (!self.enemy) return;
  const r = range_to(self, self.enemy);

  if (r <= RANGE_MELEE && self.monsterinfo.melee_debounce_time <= level.time) {
    M_SetAnimation(self, infantry_move_attack2, false);
  } else if (M_CheckClearShot(self, monsterFlashOffset()[MonsterMuzzleflashIdT.MZ2_INFANTRY_MACHINEGUN_1])) {
    if (self.count) {
      M_SetAnimation(self, infantry_move_attack1, false);
    } else {
      M_SetAnimation(self, frandom() <= 0.1 ? infantry_move_attack5 : infantry_move_attack3, false);
      self.monsterinfo.nextframe = FRAME_attak405;
    }
  }
});

// ============================================================================
// JUMP (PGM)
// ============================================================================

function infantry_jump_now(self: EdictT): void {
  const forward = vec3(0, 0, 0);
  const up = vec3(0, 0, 0);
  AngleVectors(self.s.angles, forward, null, up);
  self.velocity = vec3_add(self.velocity, vec3_muls(forward, 100));
  self.velocity = vec3_add(self.velocity, vec3_muls(up, 300));
}

function infantry_jump2_now(self: EdictT): void {
  const forward = vec3(0, 0, 0);
  const up = vec3(0, 0, 0);
  AngleVectors(self.s.angles, forward, null, up);
  self.velocity = vec3_add(self.velocity, vec3_muls(forward, 150));
  self.velocity = vec3_add(self.velocity, vec3_muls(up, 400));
}

/** rogue/g_rogue_newai.cpp:101-116. Small and self-contained (no nav_path
 *  dependency) -- ported for real. */
function monster_jump_finished(self: EdictT): boolean {
  const forward = vec3(0, 0, 0);
  AngleVectors(self.s.angles, forward, null, null);

  const fwd_speed = vec3_dot(self.velocity, forward);

  if (Math.abs(fwd_speed) < 150) {
    const z_velocity = self.velocity[2];
    self.velocity = vec3_muls(forward, 150);
    self.velocity[2] = z_velocity;
  }

  return self.monsterinfo.jump_time < level.time;
}

function infantry_jump_wait_land(self: EdictT): void {
  if (self.groundentity === null) {
    self.monsterinfo.nextframe = self.s.frame;

    if (monster_jump_finished(self)) self.monsterinfo.nextframe = self.s.frame + 1;
  } else {
    self.monsterinfo.nextframe = self.s.frame + 1;
  }
}

