function infantry_jump(self: EdictT, result: BlockedJumpResultT): void {
  if (!self.enemy) return;

  monster_done_dodge(self);

  if (result === BlockedJumpResultT.JUMP_JUMP_UP) M_SetAnimation(self, infantry_move_jump2, false);
  else M_SetAnimation(self, infantry_move_jump, false);
}

const infantry_blocked: MonsterinfoBlockedFn = RegisterMonsterinfoBlocked("infantry_blocked", (self: EdictT, dist: number): boolean => {
  const result = blocked_checkjump(self, dist);
  if (result !== BlockedJumpResultT.NO_JUMP) {
    if (result !== BlockedJumpResultT.JUMP_TURN) infantry_jump(self, result);
    return true;
  }

  if (blocked_checkplat(self, dist)) return true;

  return false;
});

const infantry_duck: MonsterinfoDuckFn = RegisterMonsterinfoDuck("infantry_duck", (self: EdictT, _eta: GTime): boolean => {
  // if we're jumping, don't dodge
  if (self.monsterinfo.active_move === infantry_move_jump || self.monsterinfo.active_move === infantry_move_jump2) {
    return false;
  }

  // don't duck during our firing or melee frames
  if (self.s.frame === FRAME_attak103 || self.s.frame === FRAME_attak315 || self.monsterinfo.active_move === infantry_move_attack2) {
    self.monsterinfo.unduck?.(self);
    return false;
  }

  M_SetAnimation(self, infantry_move_duck, false);

  return true;
});

const infantry_sidestep: MonsterinfoSidestepFn = RegisterMonsterinfoSidestep("infantry_sidestep", (self: EdictT): boolean => {
  // if we're jumping, don't dodge
  if (self.monsterinfo.active_move === infantry_move_jump || self.monsterinfo.active_move === infantry_move_jump2) {
    return false;
  }

  if (self.monsterinfo.active_move === infantry_move_run) return true;

  // Don't sidestep if we're already sidestepping, and def not unless we're actually shooting
  // or if we already cocked
  if (
    self.monsterinfo.active_move !== infantry_move_attack4 &&
    self.monsterinfo.next_move !== infantry_move_attack4 &&
    (self.s.frame === FRAME_attak103 || self.s.frame === FRAME_attak311 || self.s.frame === FRAME_attak416) &&
    !self.count
  ) {
    // give us a fire time boost so we don't end up firing for 1 frame
    self.monsterinfo.fire_wait = Gtime_add(self.monsterinfo.fire_wait, random_time(Gtime_from_ms(300), Gtime_from_ms(600)));

    M_SetAnimation(self, infantry_move_attack4, false);
  }

  return true;
});

